"// hooks/strings.ts",
"var STRINGS = { en: EN, \"zh-TW\": ZH_TW, \"zh-CN\": ZH_CN };",
"var agentLabel = (agent, s) => {",
"  if (agent === \"\")",
"    return \"\";",
"  const key = Object.hasOwn(s.agentNames, agent) ? agent : agent.toLowerCase();",
"  return Object.hasOwn(s.agentNames, key) ? s.agentNames[key] ?? agent : agent;",
"};",
