"",
"// hooks/hook-reporters.ts",
"var PROMPT_RECEIPT_SCRIPT = promptReceiptScript(boardRequestWords([EN, ZH_TW, ZH_CN]));",
"var shellQuote = (text) => `'${text.replace(/'/g, `'\\\\''`)}'`;",
"var psQuote = (text) => `'${text.replace(/'/g, \"''\")}'`;",
"var windowsQuote = (text) => `\"${text.replace(/(\\\\*)\"/g, \"$1$1\\\\\\\"\").replace(/(\\\\+)$/, \"$1$1\")}\"`;",
"var PROMPT_FILE_SCRIPT = `process.argv[1] = require('node:fs').readFileSync(process.env.AGENT_BOARD_PROMPT_INPUT, 'utf8')",
"${PROMPT_RECEIPT_SCRIPT}`;",
"var SESSION_KEYS = RECEIPT_SESSION_KEYS;",
"var PATH_KEYS = [...RECEIPT_FOLDER_KEYS, \"transcript_path\", \"transcriptPath\"];",
