"trap timed_out ALRM",
"case \"$(uname -s)\" in",
"  MINGW*|MSYS*|CYGWIN*)",
"    AGENT_BOARD_SH_AGENT=\"$agent\" AGENT_BOARD_SH_EVENT=\"$event\" AGENT_BOARD_SH_PAYLOAD=\"\\${1-}\" AGENT_BOARD_SH_INBOX=\"$dir\" powershell.exe -NoLogo -NoProfile -NonInteractive -Command ${shellQuote(powershellReporter(true))}",
