"var BASE64 = \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/\";",
"var base64 = (bytes) => {",
"  let text = \"\";",
"  for (let i = 0;i < bytes.length; i += 3) {",
"    const n = bytes[i] << 16 | (bytes[i + 1] ?? 0) << 8 | (bytes[i + 2] ?? 0);",
"    text += BASE64[n >> 18 & 63] + BASE64[n >> 12 & 63] + (i + 1 < bytes.length ? BASE64[n >> 6 & 63] : \"=\") + (i + 2 < bytes.length ? BASE64[n & 63] : \"=\");",
"  }",
"  return text;",
"};",
"var fromBase64 = (text) => {",
"  const digits = text.replace(/=+$/, \"\");",
"  const bytes = new Uint8Array(digits.length * 3 >> 2);",
"  for (let i = 0, value = 0, bits = 0, at = 0;i < digits.length; i++) {",
"    const digit = BASE64.indexOf(digits[i]);",
"    if (digit < 0)",
"      throw new Error(\"INVALID_BASE64\");",
"    value = (value << 6 | digit) & 65535;",
"    bits += 6;",
"    if (bits >= 8) {",
"      bits -= 8;",
"      bytes[at++] = value >> bits & 255;",
"    }",
"  }",
"  return bytes;",
"};",
"var utf16le = (text) => Uint8Array.from({ length: text.length * 2 }, (_, i) => i % 2 ? text.charCodeAt(i >> 1) >> 8 : text.charCodeAt(i >> 1) & 255);",
"var encodedCommandText = (encoded) => {",
"  const bytes = fromBase64(encoded);",
"  let text = \"\";",
"  for (let i = 0;i + 1 < bytes.length; i += 2)",
"    text += String.fromCharCode(bytes[i] | bytes[i + 1] << 8);",
"  return text;",
