"];",
"var directHookArgs = (command) => {",
"  const encoded = /--input-type=commonjs\\s+-e\\s+eval\\(Buffer\\.from\\('([A-Za-z0-9+/]+={0,2})','base64'\\)\\.toString\\('utf8'\\)\\)/.exec(command)?.[1];",
